head.script:
let objParent = $p.parent();



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > M > commit]<br/>컴포넌트의 입력값을 바인딩 된 DataCollection 에 즉시 반영합니다.",
    "validation" : [
        "dataMap 과 바인딩 된 경우 컴포넌트의 입력값을 바인딩 된 dataMap 에 즉시 반영합니다.",
        "ref 속성으로 dataMap 과 바인딩 된 경우 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 재생성
scwin.comp_init = function () {
    // comp 생성 호출
    objParent.scwin.comp_init();
};



scwin.btn_getText_onclick = function (e) {
    let rtn = '';

    if (objParent.target1.render.tagName !== "INPUT") {
        rtn = objParent.target1.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = objParent.target1.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }
};



// scwin.btn_setRowposition1_onclick = function (e) {
//     objParent.gdl_ref.setRowPosition(1);
// };



// scwin.btn_setRowposition2_onclick = function (e) {
