//         btn_setRowposition1.setDisabled(true);
//         btn_setRowposition2.setDisabled(true);
//     }
//     else {
//         btn_setRowposition1.setDisabled(false);
//         btn_setRowposition2.setDisabled(false);        
//     }
// };



objParent.scwin.target1_oneditkeyup = function (info, e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====commit 전=====");
    // data 확인
    wf_body_bottom.getObj("scwin").setReturnValue("data : " + objParent.gdm_ref.get("key1"));
    // text 확인
    scwin.btn_getText_onclick();       

    // commit 실행
    objParent.target1.commit();

    wf_body_bottom.getObj("scwin").setReturnValue("=====commit 후=====");

    // data 확인
    wf_body_bottom.getObj("scwin").setReturnValue("data : " + objParent.gdm_ref.get("key1"));
    // text 확인
    scwin.btn_getText_onclick();
}
